//! Cross-implementation compatibility: reads databases written by the
//! Go (and Zig-family) implementations and asserts their content.
//!
//! Fixtures live in `tests/fixtures/` (see `scripts/gen-fixtures.sh`):
//! - `test.db`: vendored from `xitdb-go/testdata/test.db`
//! - `go-golden.db`: generated by `gen-fixtures.sh` (fixed file id)

use std::fs::File;

use xitdb::arraylist::ArrayList;
use xitdb::core::{Core, FileCore};
use xitdb::counted_hashmap::CountedHashMap;
use xitdb::counted_hashset::CountedHashSet;
use xitdb::cursor::{Cursor, Writeable};
use xitdb::database::{Database, InitOpts};
use xitdb::hasher::Sha1Hasher;
use xitdb::hashmap::HashMap;
use xitdb::hashset::HashSet;
use xitdb::linked_arraylist::LinkedArrayList;
use xitdb::tag::Tag;

fn open_fixture(name: &str) -> Result<Database<FileCore, Sha1Hasher>, xitdb::error::Error> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    let file = File::open(&path).map_err(xitdb::error::Error::Io)?;
    Database::open(
        FileCore::new(file, false),
        Sha1Hasher,
        InitOpts {
            hash_id: None,
            file_id: None,
            fsync: false,
        },
    )
}

fn bytes_of<C: Core, H: xitdb::hasher::Hasher, M>(
    cursor: &Cursor<C, H, M>,
) -> Result<Vec<u8>, xitdb::error::Error> {
    cursor.read_bytes_alloc()
}

#[test]
fn reads_go_test_db_moment_0() {
    let db = open_fixture("test.db").unwrap();
    let root = db.root_cursor();
    let history = ArrayList::new(root).unwrap();

    let mc = history.get(0).unwrap().unwrap();
    let moment = HashMap::new(mc).unwrap();

    // foo / bar are inline short bytes.
    assert_eq!(
        bytes_of(&moment.get("foo").unwrap().unwrap()).unwrap(),
        b"foo"
    );
    assert_eq!(moment.get_slot("foo").unwrap().tag, Tag::ShortBytes);
    assert_eq!(moment.get_slot("bar").unwrap().tag, Tag::ShortBytes);

    // fruits: 3-list of short bytes.
    let fruits = ArrayList::new(moment.get("fruits").unwrap().unwrap()).unwrap();
    assert_eq!(fruits.count().unwrap(), 3);
    assert_eq!(
        bytes_of(&fruits.get(0).unwrap().unwrap()).unwrap(),
        b"apple"
    );

    // people: Alice 25, Bob 42.
    let people = ArrayList::new(moment.get("people").unwrap().unwrap()).unwrap();
    assert_eq!(people.count().unwrap(), 2);
    let alice = HashMap::new(people.get(0).unwrap().unwrap()).unwrap();
    assert_eq!(alice.get("age").unwrap().unwrap().read_uint().unwrap(), 25);

    // Iterate people -> person -> fields without errors.
    let mut people_seen = 0;
    for person in people.try_iter().unwrap() {
        let person = HashMap::new(person.unwrap()).unwrap();
        for kv in person.try_iter().unwrap() {
            kv.unwrap().read_key_value_pair().unwrap();
        }
        people_seen += 1;
    }
    assert_eq!(people_seen, 2);

    // todos: linked list of 3.
    let todos = LinkedArrayList::new(moment.get("todos").unwrap().unwrap()).unwrap();
    assert_eq!(todos.count().unwrap(), 3);
    assert_eq!(
        bytes_of(&todos.get(0).unwrap().unwrap()).unwrap(),
        b"Pay the bills"
    );

    // Counted map / set + plain set, 2 entries each.
    let lcm = CountedHashMap::new(moment.get("letters-counted-map").unwrap().unwrap()).unwrap();
    assert_eq!(lcm.count().unwrap(), 2);
    let mut n = 0;
    for kv in lcm.try_iter().unwrap() {
        let kv = kv.unwrap().read_key_value_pair().unwrap();
        kv.key.read_bytes_alloc().unwrap();
        n += 1;
    }
    assert_eq!(n, 2);

    let ls = HashSet::new(moment.get("letters-set").unwrap().unwrap()).unwrap();
    assert!(ls.get("a").unwrap().is_some());
    assert!(ls.get("c").unwrap().is_some());
    let mut n = 0;
    for kv in ls.try_iter().unwrap() {
        let kv = kv.unwrap().read_key_value_pair().unwrap();
        kv.key.read_bytes_alloc().unwrap();
        n += 1;
    }
    assert_eq!(n, 2);

    let lcs = CountedHashSet::new(moment.get("letters-counted-set").unwrap().unwrap()).unwrap();
    assert_eq!(lcs.count().unwrap(), 2);
    let mut n = 0;
    for kv in lcs.try_iter().unwrap() {
        let kv = kv.unwrap().read_key_value_pair().unwrap();
        kv.key.read_bytes_alloc().unwrap();
        n += 1;
    }
    assert_eq!(n, 2);
}

#[test]
fn open_with_wrong_hasher_rejects_hash_size() {
    // A 32-byte hasher cannot open a 20-byte database.
    struct BigHasher;
    impl xitdb::hasher::Hasher for BigHasher {
        fn digest_len(&self) -> usize {
            32
        }
        fn digest(&self, data: &[u8]) -> Vec<u8> {
            let mut out = vec![0u8; 32];
            out[..data.len().min(32)].copy_from_slice(&data[..data.len().min(32)]);
            out
        }
        fn id(&self) -> u32 {
            0
        }
    }
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join("test.db");
    let file = File::open(&path).unwrap();
    let err = Database::open(
        FileCore::new(file, false),
        BigHasher,
        InitOpts {
            hash_id: None,
            file_id: None,
            fsync: false,
        },
    )
    .err()
    .unwrap();
    assert!(matches!(err, xitdb::error::Error::InvalidHashSize));
}

#[test]
fn reads_go_test_db_moment_1() {
    let db = open_fixture("test.db").unwrap();
    let root = db.root_cursor();
    let history = ArrayList::new(root).unwrap();

    let mc = history.get(1).unwrap().unwrap();
    let moment = HashMap::new(mc).unwrap();

    // bar is gone.
    assert!(moment.get("bar").unwrap().is_none());

    // The stored KEY bytes read back as "fruits".
    let key = moment.get_key("fruits").unwrap().unwrap();
    assert_eq!(bytes_of(&key).unwrap(), b"fruits");

    // Fruits shrank to [lemon, ...]: 2 items.
    let fruits = ArrayList::new(moment.get("fruits").unwrap().unwrap()).unwrap();
    assert_eq!(fruits.count().unwrap(), 2);
    let kv = moment.get_key_value_pair("fruits").unwrap().unwrap();
    assert_eq!(kv.key.slot().unwrap().tag, Tag::ShortBytes);
    assert_eq!(kv.value.slot().unwrap().tag, Tag::ArrayList);
    assert_eq!(
        bytes_of(&fruits.get(0).unwrap().unwrap()).unwrap(),
        b"lemon"
    );

    // Alice is now 26; todos shrank to one item.
    let people = ArrayList::new(moment.get("people").unwrap().unwrap()).unwrap();
    assert_eq!(people.count().unwrap(), 2);
    let alice = HashMap::new(people.get(0).unwrap().unwrap()).unwrap();
    assert_eq!(alice.get("age").unwrap().unwrap().read_uint().unwrap(), 26);

    let todos = LinkedArrayList::new(moment.get("todos").unwrap().unwrap()).unwrap();
    assert_eq!(todos.count().unwrap(), 1);
    assert_eq!(
        bytes_of(&todos.get(0).unwrap().unwrap()).unwrap(),
        b"Wash the car"
    );

    let lcm = CountedHashMap::new(moment.get("letters-counted-map").unwrap().unwrap()).unwrap();
    assert_eq!(lcm.count().unwrap(), 1);

    let ls = HashSet::new(moment.get("letters-set").unwrap().unwrap()).unwrap();
    assert!(ls.get("a").unwrap().is_some());
    assert!(ls.get("c").unwrap().is_none());

    let lcs = CountedHashSet::new(moment.get("letters-counted-set").unwrap().unwrap()).unwrap();
    assert_eq!(lcs.count().unwrap(), 1);
}

#[test]
fn reads_go_golden_fixture() {
    // Generated by scripts/gen-fixtures.sh with a fixed file id; covers
    // every collection kind plus scalars, format tags, and nesting.
    let db = open_fixture("go-golden.db").unwrap();
    let root = db.root_cursor();
    let history = ArrayList::new(root).unwrap();
    assert_eq!(history.count().unwrap(), 2);

    let mc = history.get(-1).unwrap().unwrap();
    let m = HashMap::new(mc).unwrap();
    assert_eq!(m.get("uint").unwrap().unwrap().read_uint().unwrap(), 42);
    assert_eq!(m.get("int").unwrap().unwrap().read_int().unwrap(), -7);
    assert!((m.get("float").unwrap().unwrap().read_float().unwrap() - 2.5).abs() < 1e-12);
    let tagged = m
        .get("tagged")
        .unwrap()
        .unwrap()
        .read_bytes_object(&mut [0u8; 32])
        .unwrap();
    assert_eq!(tagged.value, b"abc");
    assert_eq!(tagged.format_tag, Some(*b"bi"));
    assert_eq!(
        m.get("long")
            .unwrap()
            .unwrap()
            .read_bytes_alloc()
            .unwrap()
            .len(),
        5000
    );
    let sm = xitdb::sorted_map::SortedMap::new(m.get("sorted").unwrap().unwrap()).unwrap();
    assert_eq!(sm.count().unwrap(), 3);
    let ll = LinkedArrayList::new(m.get("linked").unwrap().unwrap()).unwrap();
    assert_eq!(ll.count().unwrap(), 3);
    let hs = HashSet::new(m.get("hset").unwrap().unwrap()).unwrap();
    assert!(hs.contains("s1").unwrap());
    let chm = CountedHashMap::new(m.get("chm").unwrap().unwrap()).unwrap();
    assert_eq!(chm.count().unwrap(), 2);

    // Writable check on a scratch copy (never the fixture file itself):
    // proves layout agreement beyond reads.
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join("go-golden.db");
    let tmp = std::env::temp_dir().join(format!("xitdb-compat-{}.db", std::process::id()));
    std::fs::copy(&path, &tmp).unwrap();
    let file = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open(&tmp)
        .unwrap();
    let db = Database::open(
        FileCore::new(file, false),
        Sha1Hasher,
        InitOpts {
            hash_id: None,
            file_id: None,
            fsync: false,
        },
    )
    .unwrap();
    db.run_context(|w| {
        let history = ArrayList::new_write(w)?;
        let mc = history.put_cursor(0)?;
        let m = HashMap::new_write(&mc)?;
        m.put("probe", Writeable::Uint(1))?;
        Ok(())
    })
    .unwrap();
    std::fs::remove_file(&tmp).ok();
}
